/* Uninformed search: executable frontier, duplicate and depth-budget semantics. */
(() => {'use strict';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function parseGraph(text,start,goal){
 if(!/^[A-Za-z0-9]{1,8}$/.test(start)||!/^[A-Za-z0-9]{1,8}$/.test(goal))throw Error('State names must contain 1–8 letters or digits.');
 const edges=String(text).trim().split(/\n/).filter(x=>x.trim()).map(line=>{const p=line.trim().split(/\s+/);if(p.length!==3||p.slice(0,2).some(x=>!/^[A-Za-z0-9]{1,8}$/.test(x))||!/^\d+$/.test(p[2])||Number(p[2])>10000)throw Error('Each edge must be: source destination nonnegative-integer-cost (0–10000).');return [p[0],p[1],Number(p[2])];});
 const nodes=[...new Set([start,goal,...edges.flatMap(e=>e.slice(0,2))])];if(nodes.length>8||edges.length>16)throw Error('Use at most eight states and sixteen directed edges.');return {nodes,edges,start,goal};
}
function run(graph,algorithm='bfs',limit=4,cap=240){
 if(!['bfs','dfs','ucs','dls','ids'].includes(algorithm))throw Error('Unknown algorithm.');if(!Number.isInteger(limit)||limit<0||limit>12)throw Error('Depth limit must be an integer from 0 to 12.');
 const adj=Object.fromEntries(graph.nodes.map(x=>[x,[]]));for(const [u,v,c]of graph.edges){if(c<0||!Number.isSafeInteger(c))throw Error('Search laboratory requires nonnegative safe integer costs.');adj[u].push([v,c]);}
 const events=[];let serial=0,selected=0,expanded=0,generated=0,duplicates=0,stale=0,answer=null,termination='failure',stopped=false,iteration=algorithm==='ids'?0:limit;
 let frontier=[],best={},discovered=new Set(),current=null;
 function emit(op,why){if(events.length>=cap){stopped=true;termination='truncated';return;}const visible=algorithm==='ucs'?[...frontier].sort((a,b)=>a.g-b.g||a.serial-b.serial):frontier;events.push({operation:op,why,frontier:visible.map(n=>({state:n.s,cost:n.g,depth:n.d,path:n.path.slice()})),current:current?{state:current.s,cost:current.g,depth:current.d,path:current.path.slice()}:null,best:{...best},discovered:[...discovered],selected,expanded,generated,duplicates,stale,iteration,algorithm,limit:iteration});}
 const node=(s,g,d,path)=>({s,g,d,path,serial:serial++});
 function depthVisit(n,L){if(stopped)return 'truncated';current=n;selected++;emit('Select '+n.s,'Test the goal before applying the depth boundary.');if(n.s===graph.goal){answer=n;emit('Return goal','The selected node satisfies the goal test.');return 'success';}if(n.d===L){emit('Cutoff','A nonglobal failure cannot be inferred from reaching the depth bound.');return 'cutoff';}expanded++;let cutoff=false;emit('Expand '+n.s,'Generate successors in the declared edge-list order.');for(const [v,c]of adj[n.s]){generated++;if(n.path.includes(v)){duplicates++;emit('Reject path cycle','A state already on this path need not be revisited in this static reachability model.');continue;}const ch=node(v,n.g+c,n.d+1,[...n.path,v]);frontier.push(ch);emit('Push '+v,'Keep this path with its own remaining depth budget.');const outcome=depthVisit(ch,L);frontier.pop();if(outcome==='success'||outcome==='truncated')return outcome;if(outcome==='cutoff')cutoff=true;current=n;emit('Backtrack','Return to the caller and continue its next successor.');}return cutoff?'cutoff':'failure';}
 if(algorithm==='dls'||algorithm==='ids'){
  for(let L=algorithm==='ids'?0:limit;L<=limit;L++){iteration=L;const root=node(graph.start,0,0,[graph.start]);frontier=[root];generated++;emit('Start depth limit '+L,'Each iteration uses fresh path-cycle information; counters accumulate across IDS iterations.');const result=depthVisit(root,L);frontier=[];termination=result;if(result==='success'||result==='failure'||result==='truncated')break;}
 }else{
  const root=node(graph.start,0,0,[graph.start]);frontier=[root];best[graph.start]=0;discovered.add(graph.start);generated=1;emit('Initialize frontier','The root is included in generated-node counts.');
  while(frontier.length&&!stopped){if(algorithm==='ucs')frontier.sort((a,b)=>a.g-b.g||a.serial-b.serial);const n=algorithm==='dfs'?frontier.pop():frontier.shift();current=n;
   if(algorithm==='ucs'&&n.g!==best[n.s]){stale++;emit('Discard stale entry','A strictly cheaper record for this state is already known.');continue;}
   selected++;emit('Select '+n.s,'A valid removal is counted as selected; a goal is not expanded.');if(n.s===graph.goal){answer=n;termination='success';emit('Return goal','Goal testing on valid removal respects the frontier ordering.');break;}expanded++;emit('Expand '+n.s,'Each outgoing edge generates a candidate before duplicate filtering.');let children=[];
   for(const [v,c]of adj[n.s]){generated++;const ch=node(v,n.g+c,n.d+1,[...n.path,v]);if(algorithm==='ucs'){if(best[v]===undefined||ch.g<best[v]){best[v]=ch.g;frontier.push(ch);emit('Relax '+v,'Strict improvement preserves cheaper paths and prevents equal-cost zero-cycle reinsertion.');}else{duplicates++;emit('Reject dominated '+v,'The candidate does not improve the best recorded cost.');}}
    else if(discovered.has(v)){duplicates++;emit('Reject duplicate '+v,'Global discovery on insertion prevents repeated finite-graph expansion.');}else{discovered.add(v);children.push(ch);if(algorithm==='bfs'){frontier.push(ch);emit('Enqueue '+v,'FIFO preserves nondecreasing path depth.');}}
   }
   if(algorithm==='dfs'){for(const ch of children.reverse())frontier.push(ch);emit('Push children in reverse order','The first listed successor is removed next from the LIFO stack.');}
  }
 }
 if(stopped)termination='truncated';if(termination!=='success'){current=null;emit('Stop: '+termination,termination==='truncated'?'The event budget ended. This is not evidence of failure.':termination==='cutoff'?'The maximum requested depth bound was reached. A deeper solution may exist.':'The finite reachable search space was exhausted.');}
 return {events,result:{termination,path:answer?.path||null,cost:answer?.g??null,depth:answer?.d??null,selected,expanded,generated,duplicates,stale},graph,algorithm,limit};
}
const tx=(x,y,s,anchor='start',math=false)=>`<text x="${x}" y="${y}" text-anchor="${anchor}" class="us-${math?'math':'label'}">${esc(s)}</text>`;
const rect=(x,y,w,h,c='#e6efea')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="7" fill="${c}" stroke="#a2b9b4"/>`;
const svg=s=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 640" role="img" data-visual-type="search-graph"><defs><marker id="us-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,1 L9,5 L0,9" fill="none" stroke="context-stroke" stroke-width="1.4"/></marker></defs>${s}</svg>`;
const math=s=>'<math xmlns="http://www.w3.org/1998/Math/MathML"><mtext>'+esc(s)+'</mtext></math>';
function drawGraph(graph,event,positions){
 const depth={[graph.start]:0},q=[graph.start];for(let i=0;i<q.length;i++)for(const [u,v]of graph.edges)if(u===q[i]&&depth[v]===undefined){depth[v]=depth[u]+1;q.push(v);}const maxDepth=Math.max(1,...Object.values(depth));for(const v of graph.nodes)if(depth[v]===undefined)depth[v]=maxDepth;const layers={};for(const v of graph.nodes)(layers[depth[v]]??=[]).push(v);
 const pos=positions||Object.fromEntries(graph.nodes.map(v=>{const layer=layers[depth[v]],i=layer.indexOf(v);return [v,[90+820*depth[v]/maxDepth,layer.length===1?225:100+250*i/(layer.length-1)]];}));let s=tx(35,35,event.operation),r=30;
 for(const [u,v,c]of graph.edges){const [x,y]=pos[u],[a,b]=pos[v],dx=a-x,dy=b-y,len=Math.hypot(dx,dy);if(!len){s+=`<path d="M${x-20},${y-24} C${x-85},${y-105} ${x+85},${y-105} ${x+20},${y-24}" fill="none" stroke="#6a8997" marker-end="url(#us-arrow)"/>`+tx(x,y-83,c,'middle',true);continue;}const ox=-dy/len*12,oy=dx/len*12; s+=`<line x1="${x+dx/len*r}" y1="${y+dy/len*r}" x2="${a-dx/len*(r+3)}" y2="${b-dy/len*(r+3)}" stroke="#6a8997" stroke-width="2" marker-end="url(#us-arrow)"/>`+tx((x+a)/2+ox,(y+b)/2+oy-5,c,'middle',true);}
 for(const v of graph.nodes){const [x,y]=pos[v],hot=event.current?.state===v,fill=v===graph.goal?'#ead8ad':hot?'#bad5d2':'#edf3f3';s+=`<g data-entity="node-${v}"><circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="#487286" stroke-width="2"/>`+tx(x,y+6,v,'middle',true)+'</g>';}
 if(event.current){const [x,y]=pos[event.current.state];s+=`<g data-entity="selected-cursor"><circle cx="${x}" cy="${y}" r="38" fill="none" stroke="#b77d37" stroke-width="3"/></g>`;}
 s+=tx(35,415,event.algorithm==='dfs'?'Stack bottom → top':event.algorithm==='ucs'?'Priority records: cost; stable insertion ties':event.algorithm==='dls'||event.algorithm==='ids'?'Active recursion path; remaining budget belongs to each path':'Queue front → back');
 let fr=event.frontier.slice(0,6);for(let i=0;i<fr.length;i++){const v=fr[i],x=35+i*153;s+=`<g data-entity="frontier-${v.path.join('-')}">`+rect(x,440,139,76)+tx(x+69,469,v.state+' · g='+v.cost,'middle',true)+tx(x+69,498,'depth '+v.depth,'middle')+'</g>';}
 if(event.frontier.length>6)s+=tx(35,545,'Additional records: '+(event.frontier.length-6)+'; the complete ordered frontier is shown in the state panel.');
 s+=tx(35,580,'Selected '+event.selected+' · expanded '+event.expanded+' · generated '+event.generated+' · rejected '+event.duplicates+' · stale '+event.stale)+tx(35,615,'Directed edges; labels are costs. Goal: '+graph.goal+'. Limit: '+event.limit+'.');return svg(s);
}
function makeModel(id,title,trace,positions){const m={id,title,kind:'search-graph',invariant:'Every checkpoint records the complete frontier and counters. A node is selected on valid removal and expanded only if successors are inspected.',code:['Initialize the frontier.','Select a node according to the algorithm.','Test the goal; otherwise expand.','Filter duplicates or relax a cheaper cost.','Repeat or report a qualified stopping outcome.'],frames:[],result:trace.result};
 for(const event of trace.events){const prev=m.frames.at(-1)?.snapshot;const snapshot=JSON.parse(JSON.stringify(event));m.frames.push({snapshot,svg:drawGraph(trace.graph,event,positions),caption:event.why,formulaHtml:math('Selected: '+event.selected+'; expanded: '+event.expanded+'; generated: '+event.generated),teaching:{operation:event.operation,why:event.why,checks:[{mathHtml:math('generated ≥ selected'),result:String(event.generated>=event.selected)}],changes:prev?Object.entries(snapshot).filter(([k,v])=>JSON.stringify(prev[k])!==JSON.stringify(v)).map(([field,after])=>({field,before:prev[field],after})):[],currentState:snapshot,initial:!prev,reading:m.invariant,guide:m.code,activeLine:Math.min(4,m.frames.length?1:0),mode:m.kind}});}
 return m;
}
const api={parseGraph,run,makeModel,drawGraph};if(typeof module!=='undefined'){module.exports=api;return;}globalThis.SearchModels=api;
function mount(host,m){return AdvancedSimulations.mount(host,m,{topic:"i_uninformed",prefix:"us"});}



const controls=()=>'<div class="us-controls"><button type="button" data-reset>Restart</button><button type="button" data-prev>Previous</button><button type="button" data-play>Play</button><button type="button" data-next>Next</button><label>Speed<select data-speed><option value="2600">Slow</option><option value="1800" selected>Normal</option><option value="1300">Fast</option></select></label><label>Step<input type="range" data-seek min="0" value="0" aria-label="Laboratory checkpoint"></label></div><div class="us-stage"></div><p class="us-caption"></p><p data-progress></p><div class="us-formula formula-block"></div><div class="us-print"></div>';
async function boot(){const data=await(await fetch('i_uninformed-models.json')).json();globalThis.SearchPlayers=[];for(const host of document.querySelectorAll('[data-us-model]')){const m=data.models.find(x=>x.id===host.dataset.usModel);if(!m)throw Error('Missing search model.');SearchPlayers.push(mount(host,m));}const form=document.querySelector('#us-form'),out=document.querySelector('#us-output'),error=document.querySelector('#us-error');let current=null;
 form.addEventListener('submit',event=>{event.preventDefault();try{const f=form.elements,g=parseGraph(f.edges.value,f.start.value.trim(),f.goal.value.trim()),r=run(g,f.algorithm.value,Number(f.limit.value)),m=makeModel('editable-search','Your directed search graph',r);current?.dispose();out.innerHTML='<section class="us-model" tabindex="0"><h3>'+esc(m.title)+'</h3><p>'+esc(m.invariant)+'</p>'+controls()+'</section><section class="lab-results"><h3>Search outcome</h3><p>Outcome: '+esc(r.result.termination)+'. Path: '+esc(r.result.path?.join(' → ')||'none returned')+'. Cost: '+esc(r.result.cost??'not defined')+'. Depth: '+esc(r.result.depth??'not defined')+'.</p><p>The event cap is 240 checkpoints. Truncated and cutoff outcomes do not prove that no solution exists. Edge-list order breaks BFS/DFS ties; UCS uses stable insertion order for equal costs. DLS/IDS use path-cycle checks rather than a global Boolean visited set.</p></section>';current=mount(out.firstChild,m);globalThis.SearchLab=current;error.textContent='';}catch(err){error.textContent=err.message;}});form.dispatchEvent(new Event('submit',{cancelable:true}));}
boot().catch(err=>{const p=document.createElement('p');p.setAttribute('role','alert');p.textContent='Search laboratory could not initialize: '+err.message;document.querySelector('.lesson').prepend(p);throw err;});})();
